// ── 1. SQL Injection: vulnerable vs parameterized ────────────

// VULNERABLE — string concatenation: NEVER do this
function getUserVulnerable(db, email) {
  // If email = "' OR '1'='1" this becomes:
  // SELECT * FROM users WHERE email = '' OR '1'='1'
  // Returns every user in the database
  const sql = `SELECT * FROM users WHERE email = '${email}'`;
  return db.query(sql);
}

// SAFE — parameterized query (node-postgres syntax)
function getUserSafe(db, email) {
  // Template is compiled first; email is ALWAYS treated as data
  return db.query('SELECT * FROM users WHERE email = $1', [email]);
}

// SAFE — with named parameters (better-sqlite3 syntax)
function getUserSafeNamed(db, email) {
  const stmt = db.prepare('SELECT * FROM users WHERE email = :email');
  return stmt.get({ email }); // email value can never alter query structure
}

// ── 2. XSS: safe DOM insertion patterns ──────────────────────

// VULNERABLE — treats string as HTML, executes injected scripts:
// element.innerHTML = userInput;
// document.write(userInput);
// element.outerHTML = `<div>${userInput}</div>`;

// SAFE — textContent always renders as plain text, never HTML:
function setUserContent(element, userInput) {
  element.textContent = userInput; // Safe: XSS impossible via this path
}

// Manual HTML encoder — for contexts where you must use innerHTML:
function htmlEncode(str) {
  return String(str)
    .replace(/&/g, '&amp;')   // MUST come first
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

