// ── 3. Setting security headers (Express middleware) ─────────
function securityHeaders(req, res, next) {
  // Prevent browsers from MIME-sniffing responses
  res.setHeader('X-Content-Type-Options', 'nosniff');
  // Prevent clickjacking — page cannot be embedded in an iframe
  res.setHeader('X-Frame-Options', 'DENY');
  // Force HTTPS for 1 year (HSTS)
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  // Content Security Policy — only allow scripts from same origin
  res.setHeader('Content-Security-Policy',
    "default-src 'self'; script-src 'self'; object-src 'none'; base-uri 'self'"
  );
  next();
}

// ── CSRF token: generate, embed, validate ─────────────────────
import { randomBytes, timingSafeEqual } from 'node:crypto';

// Generate a 256-bit unpredictable token and store in session
function issueCsrfToken(session) {
  const token = randomBytes(32).toString('hex'); // 64 hex chars
  session.csrfToken = token;
  return token; // embed in form as hidden input or X-CSRF-Token header
}

// Validate on every state-changing request (POST/PUT/PATCH/DELETE)
function validateCsrf(session, submittedToken) {
  const stored = session.csrfToken;
  if (!stored || !submittedToken) return false;
  // MUST use constant-time comparison — early exit leaks timing info
  const a = Buffer.from(stored, 'hex');
  const b = Buffer.from(submittedToken, 'hex');
  if (a.length !== b.length) return false;
  return timingSafeEqual(a, b);
}

// Express middleware using the above
function csrfMiddleware(req, res, next) {
  if (['GET', 'HEAD', 'OPTIONS'].includes(req.method)) return next(); // read-only safe
  const token = req.headers['x-csrf-token'] ?? req.body?._csrf;
  if (!validateCsrf(req.session, token)) {
    return res.status(403).json({ error: 'CSRF validation failed' });
  }
  next();
}

// ── SSRF mitigation: allowlist + post-DNS IP check ────────────
import dns from 'node:dns/promises';
import { URL } from 'node:url';

// Private IP ranges that servers must never request
const PRIVATE_RANGES = [
  /^10\.\d+\.\d+\.\d+$/,           // 10.0.0.0/8
  /^172\.(1[6-9]|2\d|3[01])\.\d+\.\d+$/,  // 172.16.0.0/12
  /^192\.168\.\d+\.\d+$/,         // 192.168.0.0/16
  /^127\.\d+\.\d+\.\d+$/,         // Loopback
  /^169\.254\.\d+\.\d+$/,         // Link-local / AWS IMDS
  /^::1$/,                         // IPv6 loopback
  /^fc00:/,                        // IPv6 unique local
];

const ALLOWED_DOMAINS = ['.example.com', '.trusted-api.io'];

async function isSafeToFetch(rawUrl) {
  let url;
  try { url = new URL(rawUrl); } catch { return false; }

  // Step 1: only allow http/https — block file://, ftp://, gopher://, etc.
  if (!['http:', 'https:'].includes(url.protocol)) return false;

  // Step 2: domain allowlist (checked against the hostname before DNS)
  const domainAllowed = ALLOWED_DOMAINS.some(d => url.hostname.endsWith(d));
  if (!domainAllowed) return false;

  // Step 3: resolve DNS NOW and check resolved IPs — defeats DNS rebinding
  const ips = await dns.resolve4(url.hostname).catch(() => []);
  if (ips.length === 0) return false; // unresolvable
  const hasPrivateIp = ips.some(ip => PRIVATE_RANGES.some(r => r.test(ip)));
  if (hasPrivateIp) return false;

  return true;
}

// Usage: always use isSafeToFetch before fetching any user-provided URL
async function safeWebhookFetch(userUrl) {
  if (!await isSafeToFetch(userUrl)) {
    throw new Error('URL not permitted: failed SSRF validation');
  }
  return fetch(userUrl); // now safe to request
}

