// ── Content Security Policy (CSP) header — XSS defense in depth
const CSP = [
  "default-src 'self'",                     // Only load resources from same origin
  "script-src 'self' 'nonce-{RANDOM}'",    // Allow scripts from origin + nonce-tagged inline
  "style-src 'self' fonts.googleapis.com",  // Allow Google Fonts stylesheet
  "img-src 'self' data: https:",            // Images from same origin, data URIs, or HTTPS
  "connect-src 'self' api.example.com",     // XHR/fetch only to these origins
  "font-src 'self' fonts.gstatic.com",
  "frame-ancestors 'none'",                 // Block iframe embedding (anti-clickjacking)
  "base-uri 'self'",                        // Block base-tag injection
  "form-action 'self'",                     // Forms only submit to same origin
  "upgrade-insecure-requests",              // Auto-upgrade HTTP sub-resources to HTTPS
].join('; ');

